The identifiers in other vocabularies that share a UMLS concept with a source-asserted identifier.

`GET /crosswalk/{version}/source/{source}/{id}`

# Path fields
- `version::String` (default `\"current\"`): The UMLS release, such as `2024AA`, back to `2008AA`; `current` is the latest.
- `source::String`: A source vocabulary abbreviation, such as `SNOMEDCT_US` or `MSH`.
- `id::String`: A code, source concept or source descriptor identifier in the source vocabulary.

# Query fields
- `targetSource::ListParam`: Source vocabularies to cross-walk to.
- `includeObsolete::Bool`: Include obsolete content.
- `includeSuppressible::Bool`: Include suppressible content.
- `pageNumber::Int`: The page to return, from 1.
- `pageSize::Int`: The number of results on a page.
"""
@kwarg struct Crosswalk <: Endpoint{Service, :GET}
    version::String = "current" &(in = :path,)
    source::String &(in = :path,)
    id::String &(in = :path,)
    targetSource::Union{Nothing, ListParam} = nothing
    includeObsolete::Union{Nothing, Bool} = nothing
    includeSuppressible::Union{Nothing, Bool} = nothing
    pageNumber::Union{Nothing, Int} = nothing
    pageSize::Union{Nothing, Int} = nothing
end
R.template(::Type{<:Crosswalk}) = "/crosswalk/{version}/source/{source}/{id}"

"""
    SemanticType(; version, TUI)

A semantic type: its name, definition, tree number and semantic group.

`GET /semantic-network/{version}/TUI/{TUI}`

# Path fields
- `version::String` (default `\"current\"`): The UMLS release, such as `2024AA`, back to `2008AA`; `current` is the latest.
- `TUI::String`: A semantic type identifier, such as `T109`.
"""
@kwarg struct SemanticType <: Endpoint{Service, :GET}
    version::String = "current" &(in = :path,)
    TUI::String &(in = :path,)
end
R.template(::Type{<:SemanticType}) = "/semantic-network/{version}/TUI/{TUI}"

end # module
